// ───────────────────────── 鉴权 ─────────────────────────

/// 一次请求的鉴权结果:是谁、什么角色。
#[derive(Clone)]
pub struct AuthCtx {
    pub user_id: i64, // 0 = 合成身份(全局口令 admin / 本机单人 local)
    pub username: String,
    pub role: String, // owner|collaborator|visitor|lead
    /// 这条请求是**哪台设备**发来的(会话上记的 device_id;全局口令等合成身份为空)。
    /// 盘与远程执行的按设备闸靠它 —— 见 `grants::fs_gate` / `grants::exec_gate`。
    pub device_id: String,
}

pub fn bearer_of(headers: &HeaderMap) -> Option<String> {
    headers
        .get("authorization")
        .and_then(|v| v.to_str().ok())
        .map(|s| s.strip_prefix("Bearer ").unwrap_or(s).to_string())
        .or_else(|| {
            headers
                .get("x-polaris-token")
                .and_then(|v| v.to_str().ok())
                .map(|s| s.to_string())
        })
}

/// 「这台机器处于免口令模式，且**这一条请求**的来源够格」——由外壳(server.rs)按它
/// 自己那套来源判定算好，经请求扩展塞进来。没有这个扩展(桌面内嵌主机 / 老调用方)
/// 一律当 false。
///
/// 只有 [`collab_bootstrap`] 读它：免口令的 NAS 上机器根本没有口令可出示，
/// 不认这条闸就永远建不出第一个账号 —— 协作/团队整条线直接锁死。
/// 其余端点照旧只认真会话，`resolve_auth` 也绝不因此合成 owner。
#[derive(Clone, Copy, Debug)]
pub struct OpenGate(pub bool);

/// token(header 或 ws query) → AuthCtx。None = 未授权。
pub fn resolve_auth(auth_token: &Option<String>, token: Option<&str>) -> Option<AuthCtx> {
    // 轨② 全局口令 = owner。
    if let Some(expected) = auth_token.as_ref() {
        if token == Some(expected.as_str()) {
            return Some(AuthCtx {
                user_id: 0,
                username: "admin".into(),
                role: "owner".into(),
                device_id: String::new(),
            });
        }
    }
    // 轨① 会话 token。
    if let Some(t) = token {
        if let Ok((u, device_id)) = crate::collab::auth::check_session_with_device(t) {
            return Some(AuthCtx {
                user_id: u.id,
                username: u.username,
                role: u.role,
                device_id,
            });
        }
    }
    // 未命中就拒绝。零账号/无全局口令也绝不能合成 owner：否则攻击者可先调用
    // owner-only 的票据接口，再 redeem 绕过 bootstrap 初始化口令。
    None
}

/// header → AuthCtx。鉴权的同步 SQLite 查询挪进阻塞线程池:直接跑在 axum async worker
/// 上会钉住 reactor(会话短缓存命中时不落库,这层 spawn_blocking 兜的是未命中/首次)。
pub async fn auth_ctx(state: &CollabState, headers: &HeaderMap) -> Option<AuthCtx> {
    let auth_token = state.auth_token.clone();
    let token = bearer_of(headers);
    tokio::task::spawn_blocking(move || resolve_auth(&auth_token, token.as_deref()))
        .await
        .ok()
        .flatten()
}

/// 盘的入方向闸:**角色**或**设备契约**,两条路任一通过即可。
///
/// 为什么不能只留角色闸:设备码那条路进来的是 visitor,角色闸(owner 级)会把它一刀切死,
/// 「拿码就能连、默认只读」根本走不通。为什么不能只留契约闸:桌面自己、owner 令牌、
/// 老手机壳走的会话没有设备契约,只认契约会把它们全挡在外面。
///
/// 判定顺序:**先看契约**(它是用户在台账上亲手调的档,优先级最高,连 owner 角色也压得住 ——
/// 冷静期里的自己人也该只读),契约没话说才退回角色闸。
fn fs_allowed(ctx: &AuthCtx, need_write: bool) -> Result<(), String> {
    crate::collab::grants::fs_gate(&ctx.device_id, need_write)?;
    // 契约放行了,还要够角色 —— 除非它本来就是被契约放进来的那种设备。
    if role_rank(&ctx.role) >= 3 || has_grant(&ctx.device_id) {
        return Ok(());
    }
    Err("需要 owner 权限".into())
}

/// 这台设备有没有一行信任契约(有 = 它是经「设备码 / 同账号设备网」正式放进来的)。
fn has_grant(device_id: &str) -> bool {
    !device_id.trim().is_empty()
        && matches!(crate::collab::grants::get(device_id), Ok(Some(g)) if !g.revoked)
}

pub fn role_rank(role: &str) -> u8 {
    match role {
        "owner" => 3,
        "lead" | "collaborator" => 2,
        "visitor" => 1,
        _ => 0,
    }
}

// ───────────────────────── 小工具 ─────────────────────────

fn s_of(v: &Value, k: &str) -> String {
    v.get(k).and_then(|x| x.as_str()).unwrap_or("").to_string()
}

fn i_of(v: &Value, k: &str) -> Option<i64> {
    v.get(k).and_then(|x| x.as_i64())
        .route(
            "/api/fs/write",
            axum::routing::put(fs_write_api)
                .layer(axum::extract::DefaultBodyLimit::max(4 * 1024 * 1024 * 1024)),
        )
        .route("/api/fs/op/:op", post(fs_op_api));
    // 云机中继网关(collab-net 才有):主机挂牌 + /h/:id 反代到该主机(经 iroh 到桌面 apihub)。
    #[cfg(feature = "collab-net")]
    {
        r = r.route("/api/gw/register", post(gw_register)).route(
            "/h/:host_id/*rest",
            axum::routing::any(crate::collab::gateway::gateway_proxy)
                .layer(axum::extract::DefaultBodyLimit::max(512 * 1024 * 1024)),
        );
    }
    if with_ws {
        r = r.route("/ws", get(collab_ws_handler));
    }
    r.layer(axum::middleware::from_fn(risk_middleware)).with_state(state)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Range 解析:标准/开区间/后缀/越界钳制/看不懂回 None(整文件)。
    #[test]
    fn byte_range_parsing() {
        assert_eq!(parse_byte_range(Some("bytes=0-99"), 1000), Some((0, 99)));
        assert_eq!(parse_byte_range(Some("bytes=200-"), 1000), Some((200, 999)));
        assert_eq!(parse_byte_range(Some("bytes=-100"), 1000), Some((900, 999)));
        assert_eq!(
            parse_byte_range(Some("bytes=0-9999"), 1000),
            Some((0, 999)),
            "end 越界须钳到 len-1"
        );
        assert_eq!(
            parse_byte_range(Some("bytes=500-100"), 1000),
            None,
            "倒置区间无效,按整文件"
        );
        assert_eq!(
            parse_byte_range(Some("bytes=2000-"), 1000),
            None,
            "起点越界不可满足,按整文件"
        );
        assert_eq!(parse_byte_range(None, 1000), None);
        assert_eq!(parse_byte_range(Some("items=0-1"), 1000), None);
        assert_eq!(
            parse_byte_range(Some("bytes=-0"), 1000),
            None,
            "-0 无意义按整文件"
        );
        assert_eq!(
            parse_byte_range(Some("bytes=-100"), 0),
            None,
            "空文件后缀区间按整文件"
        );
        // 多区间只取第一段。
        assert_eq!(parse_byte_range(Some("bytes=0-1,5-9"), 1000), Some((0, 1)));
        assert_eq!(httpdate_from_secs(0), "Thu, 01 Jan 1970 00:00:00 GMT");
    }

    /// 已压缩格式不再二次压缩(白烧 CPU),其余一律可压。判不准不致命 —— zstd 对
    /// 不可压数据是原样存储 —— 但这份名单直接决定小机器上的 CPU 账单。
    #[test]
    fn precompressed_ext_detection() {
        for p in [
            "a/b/photo.JPG",
            "x.zip",
            "dir/pkg.tar.gz",
            "v.mp4",
            "s.pdf",
            "app.exe",
        ] {
            assert!(is_precompressed(p), "{p} 应判为已压缩");
        }
        for p in [
            "notes.md",
            "src/main.rs",
            "a.txt",
            "data.json",
            "server.log",
            "无扩展名",
        ] {
            assert!(!is_precompressed(p), "{p} 应判为可压缩");
        }
        // 目录名里的点不能误当扩展名。
        assert!(!is_precompressed("v1.2.3/README"), "只看最后一段的扩展名");
    }

    /// 压缩级别的钳制与关闭开关。0 = 彻底不压(链路是千兆内网时该关)。
    #[test]
    fn zstd_level_clamped() {
        std::env::set_var("POLARIS_FS_ZSTD_LEVEL", "0");
        assert_eq!(zstd_level(), 0, "0 = 关闭压缩");
        std::env::set_var("POLARIS_FS_ZSTD_LEVEL", "99");
        assert_eq!(zstd_level(), 19, "超出上限须钳住,不能把 CPU 烧穿");
        std::env::set_var("POLARIS_FS_ZSTD_LEVEL", "不是数字");
        assert_eq!(zstd_level(), 3, "写错按默认,不因配置错误退化成不可用");
        std::env::remove_var("POLARIS_FS_ZSTD_LEVEL");
    }

    /// 自动探测与 env 覆写合在一个测试里跑:环境变量是进程级的,拆成两个测试
    /// 会因并行执行互相污染(一个设着 POLARIS_ADVERTISE_URL,另一个恰好读到)。
    #[test]
    fn advertise_urls_autodetect_and_env_override() {
        std::env::remove_var("POLARIS_ADVERTISE_URL");
        for u in detect_advertise_urls(8484) {
            assert!(u.starts_with("http://"));
            assert!(!u.contains("127.0.0.1"));
            assert!(!u.contains("//198.18.") && !u.contains("//198.19."));
            assert!(u.ends_with(":8484"));
        }
        std::env::set_var(
            "POLARIS_ADVERTISE_URL",
            "http://nas.example:9000/, https://p.example",
        );
        let urls = detect_advertise_urls(8484);
        std::env::remove_var("POLARIS_ADVERTISE_URL");
        assert_eq!(
            urls,
            vec![
                "http://nas.example:9000".to_string(),
                "https://p.example".to_string()
            ]
        );
    }

    #[test]
    fn tun_fake_ip_range_detection() {
        let ip = |s: &str| s.parse::<std::net::IpAddr>().unwrap();
        assert!(is_tun_fake_ip(&ip("198.18.0.1")));
        assert!(is_tun_fake_ip(&ip("198.19.255.254")));
        assert!(!is_tun_fake_ip(&ip("198.17.0.1")));
        assert!(!is_tun_fake_ip(&ip("198.20.0.1")));
        assert!(!is_tun_fake_ip(&ip("192.168.1.5")));
        assert!(!is_tun_fake_ip(&ip("100.126.0.21")));
    }
}
// 设备清单、换一张 5 分钟身份断言),换不到任何一台设备的访问权。

/// 设备密钥入口闸。密钥无效/被吊销 → 403 并带上原因(客户端据此决定「重新入网」)。
// ───────────────────────── 设备信任契约 /api/peer/*(每台主机本地)─────────────────────────
//
// 与上面 /api/mesh/* 的分工要分清,这是整套设计的关键一刀:
//  · /api/mesh/*  在**云端**,回答「我有哪些设备」——目录,不含任何权限。
//  · /api/peer/*  在**本机**,回答「这台设备在我这儿能干什么」——权限,云端永远碰不到。
// 云机被完全拿下也改不动任何一台机器的 peer_grants:它根本没有这张表。

/// 本机的设备信任契约清单(owner 才看得到:这是权限面)。
async fn peer_grants_list(State(state): State<CollabState>, headers: HeaderMap) -> Response {
    let Some(ctx) = auth_ctx(&state, &headers).await else {
        return forbid();
    };
    if role_rank(&ctx.role) < 3 {
        return forbid();
    }
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let list: Vec<Value> = crate::collab::grants::list()?
            .into_iter()
            .map(|g| {
                json!({
                    "nodeId": g.node_id, "uid": g.uid, "name": g.name, "role": g.role,
                    "fsAccess": g.fs_access, "execAccess": g.exec_access,
                    // 实际生效的档(冷静期内会低于用户批的档)—— UI 要显示这个,
                    // 只显示库里那个会让用户以为「明明给了可写怎么写不进去」。
                    "effectiveFs": g.effective_fs(), "effectiveExec": g.effective_exec(),
                    "autoMount": g.auto_mount, "driveHint": g.drive_hint,
                    "cooldownUntil": g.cooldown_until, "inCooldown": g.in_cooldown(),
                    "grantedAt": g.granted_at, "grantedBy": g.granted_by, "revoked": g.revoked,
                })
            })
            .collect();
        Ok(json!({ "grants": list, "ownerUid": crate::collab::authority::owner_uid() }))
    })
    .await;
    unwrap_api(out)
}

/// 改一台设备的档位(盘 none/ro/rw、执行 none/ask/allow、自动挂载)。owner 才行。
async fn peer_grant_set(
    State(state): State<CollabState>,
    headers: HeaderMap,
    Json(v): Json<Value>,
) -> Response {
    let Some(ctx) = auth_ctx(&state, &headers).await else {
        return forbid();
    };
    if role_rank(&ctx.role) < 3 {
        return forbid();
    }
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let opt = |k: &str| v.get(k).and_then(|x| x.as_str()).map(|s| s.to_string());
        let g = crate::collab::grants::update(
            &s_of(&v, "nodeId"),
            opt("name").as_deref(),
            opt("fsAccess").as_deref(),
            opt("execAccess").as_deref(),
            v.get("autoMount").and_then(|x| x.as_bool()),
            &ctx.username,
        )?;
        Ok(json!({ "ok": true, "effectiveFs": g.effective_fs(), "autoMount": g.auto_mount }))
    })
    .await;
    unwrap_api(out)
}

/// 「信任这台设备」:冷静期立即清零(同时也把误撤销的恢复回来)。
async fn peer_grant_trust(
    State(state): State<CollabState>,
    headers: HeaderMap,
    Json(v): Json<Value>,
) -> Response {
    let Some(ctx) = auth_ctx(&state, &headers).await else {
        return forbid();
    };
    if role_rank(&ctx.role) < 3 {
        return forbid();
    }
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let g = crate::collab::grants::trust_fully(&s_of(&v, "nodeId"), &ctx.username)?;
        Ok(json!({ "ok": true, "effectiveFs": g.effective_fs() }))
    })
    .await;
    unwrap_api(out)
}

/// 撤销一台设备在**本机**的准入(丢了电脑 / 冷静期内反悔)。
///
/// 与云端的 `/api/mesh/revoke` 是两道独立的闸,应该都点:云端那道让它拿不到新断言,
/// 本机这道让它连断言都递不进来。云机被绕过、名册被伪造,本机这一行仍然说了算。
async fn peer_grant_revoke(
    State(state): State<CollabState>,
    headers: HeaderMap,
    Json(v): Json<Value>,
) -> Response {
    let Some(ctx) = auth_ctx(&state, &headers).await else {
        return forbid();
    };
    if role_rank(&ctx.role) < 3 {
        return forbid();
    }
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        crate::collab::grants::revoke(&s_of(&v, "nodeId"), &ctx.username)?;
        Ok(json!({ "ok": true }))
    })
    .await;
    unwrap_api(out)
}

/// 把自己账号名下的一台设备移出设备网(丢了电脑的应急操作)。


// ───────────────────────── 远程文件写入(挂载盘的读写面)─────────────────────────
//
// 写比读危险一个量级 —— 远端能删你的文件。所以这批端点有**两道**独立的闸:
//  ① 角色闸:与读同一条线(owner 级)。挂载端拿的是同账号断言换来的本机会话。
//  ② 目录闸:fsface 逐根的写位。角色够了但目录没开写 → 一律拒。
// 两道都得过。少任何一道,「同账号自动组网」就变成「谁进得来谁就能删盘」。

//! Same-account enrollment preserves existing explicit permissions.
use super::*;

pub fn auto_grant_self(
    node_id: &str,
    uid: &str,
    name: &str,
    _is_first_device: bool,
) -> Result<(Grant, bool), String> {
    let node_id = node_id.trim();
    if node_id.is_empty() {
        return Err("缺 NodeId".into());
    }
    if let Some(g) = get(node_id)? {
        return Ok((g, false));
    }
    let t = now();
    let conn = open_db()?;
    conn.execute(
        "INSERT INTO peer_grants(node_id,uid,name,role,fs_access,exec_access,auto_mount,\
         drive_hint,cooldown_until,granted_at,granted_by,revoked) \
         VALUES(?1,?2,?3,'owner',?4,?5,1,'',?6,?7,'auto:same-account',0)",
        params![
            node_id,
            uid.trim(),
            name.trim(),
            FS_RW,
            EXEC_ALLOW,
            0,
            t
        ],
    )
    .map_err(|e| format!("登记设备契约失败: {e}"))?;
    db::audit(
        uid,
        "peer.grant.auto",
        node_id,
        "同账号设备·策略 B 全权",
    );
    Ok((get(node_id)?.ok_or("刚写入的契约读不回来")?, true))
}

